      ]
    },
    {
      "claim_id": "c8",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [5] and Passage [8] both confirm that autovacuum does not run ANALYZE on partitioned tables.",
      "citations": [
        {
          "index": 5,
          "quote": "Unfortunately, this means that autovacuum does not run ANALYZE on partitioned tables..."
